\title{Canonical Divisors and Riemann--Roch on Complete Graphs}
\author{Aristotle}
\date{July 19, 2026}

\begin{document}
\maketitle

\begin{abstract}
Divisor theory on finite graphs translates linear equivalence into chip-firing and gives a discrete Riemann--Roch theorem. We develop the canonical calculation for the complete graph $K_n$ from first principles, emphasizing two normalization issues. The canonical divisor is $K_G(v)=\operatorname{val}(v)-2$, while Baker--Norine rank $r(D)$ differs from the dimension $\ell(D)=r(D)+1$. We prove that the zero divisor on a nonempty graph has rank zero. For $K_n$ we derive valency $n-1$, canonical coefficient $n-3$, genus $(n-1)(n-2)/2$, and canonical degree $n(n-3)=2g-2$. The graph Riemann--Roch identity then gives $r(K_G)=g(G)-1$, and hence $r(K_{K_n})=(n-1)(n-2)/2-1$. The cases $n=3,4,5,6$ are evaluated explicitly. Algorithms and connections with Laplacian lattices, parking functions, critical groups, spanning trees, and permutohedral geometry are also discussed.
\end{abstract}

\section{Introduction}
The classical Riemann--Roch theorem relates divisors on an algebraic curve to its genus and canonical divisor. Baker--Norine divisor theory replaces the curve by a finite connected graph and rational functions by integer-valued firing scripts. A divisor becomes an integer configuration on the vertices. Firing redistributes chips locally without changing their total, and linear equivalence records which configurations are reachable from one another.

The graph theorem retains the characteristic balance
\[
r(D)-r(K_G-D)=\deg(D)+1-g(G).
\]
Complete graphs are particularly transparent because all elementary invariants have closed forms. They also expose two possible convention errors. Replacing valency minus $2$ by valency minus $1$ produces the wrong canonical degree. Calling rank $\ell$ while assigning $\ell(0)=0$ conflates rank with the shifted dimension. Correcting both points yields the expected canonical rank $g-1$.

We separate the argument into three layers. Counting determines valency, genus, and canonical degree. Degree conservation determines the rank of zero. Riemann--Roch then supplies the canonical rank. Thus the numerical calculations do not purport to prove the full Riemann--Roch theorem; they isolate its exact role.

\section{Divisors and chip-firing}
Let $G=(V,E)$ be a finite connected loopless undirected graph. Edge multiplicities may be allowed. The valency $\operatorname{val}(v)$ counts incident edge ends with multiplicity.

\begin{definition}[Divisor]
A divisor is an integer-valued function $D:V\to\mathbb Z$, written
\[
D=\sum_{v\in V}D(v)v.
\]
Its degree is $\deg(D)=\sum_{v\in V}D(v)$. It is effective if $D(v)\geq0$ for every vertex.
\end{definition}

\begin{definition}[Laplacian and equivalence]
For $f:V\to\mathbb Z$, define
\[
(\Delta f)(v)=\operatorname{val}(v)f(v)-\sum_{w\sim v}f(w).
\]
A divisor is principal if it equals $\Delta f$. Divisors $D,D'$ are linearly equivalent if $D-D'=\Delta f$ for some integer-valued $f$.
\end{definition}

Firing a vertex removes one chip along each incident edge and gives one chip to each neighbor. Depending on sign convention, firing according to $f$ changes $D$ by $-\Delta f$.

\begin{lemma}[Degree invariance]
If $D\sim D'$, then $\deg(D)=\deg(D')$.
\end{lemma}
\begin{proof}
Every edge contribution to $\sum_v(\Delta f)(v)$ occurs once positively and once negatively. Hence $\deg(\Delta f)=0$, and equivalent divisors have equal degree.
\end{proof}

\section{Rank and the zero divisor}
\begin{definition}[Baker--Norine rank]
If $D$ is not equivalent to an effective divisor, set $r(D)=-1$. Otherwise, $r(D)$ is the largest integer $q\geq0$ such that for every effective divisor $E$ of degree $q$, the divisor $D-E$ is equivalent to an effective divisor.
\end{definition}

Thus rank measures resilience under arbitrary chip removal. Another common normalization is
\[
\ell(D)=r(D)+1.
\]
A divisor with no effective representative has dimension zero, while an effective divisor of rank zero has dimension one.

\begin{theorem}[Rank of zero]
On every nonempty finite connected graph, $r(0)=0$.
\end{theorem}
\begin{proof}
The zero divisor is effective, so its rank is at least zero. Choose a vertex $v$ and let $E=v$. The divisor $-E$ has degree $-1$. Degree invariance prevents it from being equivalent to an effective divisor, all of which have nonnegative degree. Thus the zero divisor does not have rank at least one, and $r(0)=0$.
\end{proof}

\begin{corollary}
With the shifted convention, $\ell(0)=1$.
\end{corollary}

\section{Genus and the canonical divisor}
\begin{definition}[Genus]
For a finite connected graph,
\[
g(G)=|E|-|V|+1.
\]
This is the cyclomatic number, or number of independent cycles.
\end{definition}

\begin{definition}[Canonical divisor]
The canonical divisor is
\[
K_G=\sum_{v\in V}\bigl(\operatorname{val}(v)-2\bigr)v.
\]
\end{definition}

\begin{proposition}[Canonical degree]
For every finite connected graph,
\[
\deg(K_G)=2g(G)-2.
\]
\end{proposition}
\begin{proof}
The handshaking identity gives $\sum_v\operatorname{val}(v)=2|E|$. Therefore
\[
\deg(K_G)=2|E|-2|V|=2(|E|-|V|+1)-2=2g(G)-2.
\]
\end{proof}

This global identity forces the subtraction by $2$. Using valency minus $1$ would increase the degree by $|V|$ and break the relation.

\section{Complete-graph formulas}
Let $K_n$ be the loopless simple graph on $n\geq1$ labelled vertices with one edge between each pair of distinct vertices.

\begin{lemma}[Valency and edge count]
Every vertex of $K_n$ has valency $n-1$, the graph has $n(n-1)/2$ edges, and the total valency is $n(n-1)$.
\end{lemma}
\begin{proof}
A fixed vertex is adjacent to the other $n-1$ vertices. Edges are unordered pairs, so there are $\binom n2=n(n-1)/2$ of them. The total valency is twice that number.
\end{proof}

\begin{theorem}[Canonical divisor of $K_n$]
For every vertex $v$,
\[
K_{K_n}(v)=n-3,
\qquad
K_{K_n}=(n-3)\sum_{v\in V(K_n)}v.
\]
\end{theorem}
\begin{proof}
Substitute $\operatorname{val}(v)=n-1$ into the definition $K_G(v)=\operatorname{val}(v)-2$.
\end{proof}

\begin{theorem}[Genus of $K_n$]
For $n\geq1$,
\[
g(K_n)=\frac{(n-1)(n-2)}2.
\]
\end{theorem}
\begin{proof}
By the edge count,
\[
g(K_n)=\frac{n(n-1)}2-n+1=\frac{(n-1)(n-2)}2.
\]
\end{proof}

\begin{theorem}[Canonical degree of $K_n$]
For $n\geq1$,
\[
\deg(K_{K_n})=n(n-3)=2g(K_n)-2.
\]
\end{theorem}
\begin{proof}
There are $n$ equal coefficients $n-3$. Moreover,
\[
2g(K_n)-2=(n-1)(n-2)-2=n(n-3).
\]
\end{proof}

\section{Riemann--Roch and canonical rank}
\begin{theorem}[Baker--Norine Riemann--Roch]
For every divisor $D$ on a finite connected graph,
\[
r(D)-r(K_G-D)=\deg(D)+1-g(G).
\]
\end{theorem}

The theorem's substantial content is the duality between $D$ and $K_G-D$. We now record its direct canonical consequence.

\begin{theorem}[Canonical rank]
On every nonempty finite connected graph,
\[
r(K_G)=g(G)-1.
\]
\end{theorem}
\begin{proof}
Set $D=K_G$ in Riemann--Roch. Then
\[
r(K_G)-r(0)=\deg(K_G)+1-g(G).
\]
Using $r(0)=0$ and $\deg(K_G)=2g(G)-2$ yields $r(K_G)=g(G)-1$.
\end{proof}

\begin{corollary}[Complete-graph canonical rank]
For $n\geq1$,
\[
r(K_{K_n})=\frac{(n-1)(n-2)}2-1.
\]
\end{corollary}

In dimension notation, the same statement is $\ell(K_G)=g(G)$. The dimension form of Riemann--Roch is unchanged because the two added ones cancel:
\[
\ell(D)-\ell(K_G-D)=\deg(D)+1-g(G).
\]
At $D=K_G$, one must use $\ell(0)=1$, not zero. This is precisely where conflating rank and dimension creates an apparent contradiction.

\section{Explicit cases}
The requested cases are summarized in Table~\ref{tab:data}.
