from typing import Sequence

def degree(d: Sequence[int]) -> int:
    return sum(d)

def fire(d: Sequence[int], vertex: int) -> list[int]:
    n = len(d)
    if not 0 <= vertex < n:
        raise IndexError(vertex)
    out = [x + 1 for x in d]
    out[vertex] -= n
    assert degree(out) == degree(d)
    return out

state = [2, 2, 2, 2, 2]
print("start", state, "degree", degree(state))
for vertex in [0, 2, 2, 4]:
    state = fire(state, vertex)
    print("fire", vertex, state, "degree", degree(state))

from itertools import combinations_with_replacement
from typing import Iterator

def effective_divisors(n: int, degree: int) -> Iterator[tuple[int, ...]]:
    for positions in combinations_with_replacement(range(n), degree):
        values = [0] * n
        for i in positions:
            values[i] += 1
        yield tuple(values)

for q in range(4):
    values = list(effective_divisors(4, q))
    expected = 1
    for k in range(1, q + 1):
        expected = expected * (4 + k - 1) // k
    print(f"degree {q}: {len(values)} candidates; expected {expected}")

